// Serves Inter from local @fontsource files in place of the blocked Google Fonts CDN.
import { readFileSync } from 'node:fs';
const dir = '/tmp/shot/node_modules/@fontsource/inter/files/';
const faces = [
  ['cyrillic', '400', 'inter-cyrillic-400-normal.woff2'], ['cyrillic', '600', 'inter-cyrillic-600-normal.woff2'],
  ['latin', '400', 'inter-latin-400-normal.woff2'], ['latin', '600', 'inter-latin-600-normal.woff2'],
];
export async function installFontShim(page) {
  await page.route('https://fonts.googleapis.com/**', (route) => {
    const css = faces.map(([subset, weight, file]) =>
      `@font-face{font-family:'Inter';font-style:normal;font-weight:${weight};font-display:block;src:url(https://fonts.gstatic.com/shim/${file}) format('woff2');unicode-range:${subset === 'cyrillic' ? 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04FF,U+2116' : 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD'};}`).join('\n');
    route.fulfill({ status: 200, contentType: 'text/css', body: css });
  });
  await page.route('https://fonts.gstatic.com/shim/**', (route) => {
    const file = route.request().url().split('/').pop();
    route.fulfill({ status: 200, contentType: 'font/woff2', body: readFileSync(dir + file) });
  });
}
EOF
